// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Swept circle-vs-brick contact for the movement (sx,sy) -> (sx+dx, sy+dy).
// The circle is inflated into the brick (Minkowski): the ball center is a
// point moving against a rect grown by the radius, and the slab method gives
// the entry time and the face. Returns { t, axis } with t in [0,1] (0 = already
// overlapping at the start of the pass), or null when the segment never
// touches the brick. axis is 'x' | 'y' | 'corner'.
function sweptContact(sx, sy, dx, dy, brick, r) {
  const cx = brick.x + brick.w / 2;
  const cy = brick.y + brick.h / 2;
  const hx = brick.w / 2 + r;
  const hy = brick.h / 2 + r;
  const ox = sx - cx;
  const oy = sy - cy;

  let t1x;
  let t2x;
  if (Math.abs(dx) < 1e-9) {
    if (Math.abs(ox) > hx) return null; // parallel to the x-slab, outside
    t1x = -Infinity;
    t2x = Infinity;
  } else {
    t1x = (-hx - ox) / dx;
    t2x = (hx - ox) / dx;
    if (t1x > t2x) {
      const t = t1x;
      t1x = t2x;
      t2x = t;
    }
  }
  let t1y;
  let t2y;
  if (Math.abs(dy) < 1e-9) {
    if (Math.abs(oy) > hy) return null;
    t1y = -Infinity;
    t2y = Infinity;
  } else {
    t1y = (-hy - oy) / dy;
    t2y = (hy - oy) / dy;
    if (t1y > t2y) {
      const t = t1y;
      t1y = t2y;
      t2y = t;
    }
  }

  const tEnter = Math.max(t1x, t1y);
  const tExit = Math.min(t2x, t2y);
  if (tEnter > tExit || tExit < 0 || tEnter > 1) return null;

  const t = Math.max(0, tEnter);
  if (tEnter <= 0) {
    // Already overlapping at the start of the pass: the face is the one the
    // ball center is nearest to; equal distances mean a corner.
    const bestX = Math.min(Math.abs(sx - brick.x), Math.abs(sx - (brick.x + brick.w)));
    const bestY = Math.min(Math.abs(sy - brick.y), Math.abs(sy - (brick.y + brick.h)));
    const axis = Math.abs(bestX - bestY) < 1e-9 ? 'corner' : bestX < bestY ? 'x' : 'y';
    return { t, axis };
  }
  // Approaching: the slab entered last decides the face; equal entries = corner.
  const axis = Math.abs(t1x - t1y) < 1e-9 ? 'corner' : t1x > t1y ? 'x' : 'y';
  return { t, axis };
}

