// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Brick contacts are SWEPT: the whole
// movement segment is tested, so a fast ball (level 6, 50ms dt cap: 35.5px per
// frame > brick height 20 + ball diameter 14) cannot jump cleanly over a brick.
// Bricks are destroyed and scored here (pure logic); frame() only renders.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const startX = ball.x;
  const startY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: swept contact too (a 50ms step at level 6 is 35.5px, deeper than
  // the 12px band + 14px ball — an endpoint band test would be jumped over).
  // Only a descending ball bounces off the paddle.
  const moveX = ball.x - startX;
  const moveY = ball.y - startY;
  let hitT = Infinity;
  let hitAxis = null;
  let hitPaddle = false;
  const hitBricks = [];
  if (ball.vy > 0) {
    const c = sweptContact(startX, startY, moveX, moveY, paddle, ball.r);
    if (c) {
      hitT = c.t;
      hitAxis = c.axis;
      hitPaddle = true;
    }
  }

  // Bricks: swept detection over the movement segment. Every brick touched at
  // the earliest contact is destroyed, and each axis bounces at most once (the
  // seam: two bricks in one pass must not flip vy twice).
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const c = sweptContact(startX, startY, moveX, moveY, brick, ball.r);
    if (!c) continue;
    if (c.t < hitT - 1e-9) {
      hitT = c.t;
      hitAxis = c.axis;
      hitPaddle = false;
      hitBricks.length = 0;
      hitBricks.push(brick);
    } else if (Math.abs(c.t - hitT) < 1e-9) {
      hitBricks.push(brick);
    }
