// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Contacts are SWEPT and resolved in
// time order, over a bounded number of sub-passes: a fast ball (level 6, 50ms
// dt cap: 35.5px per frame > brick height 20 + ball diameter 14) cannot jump
// cleanly over a brick, and a bounce never leaves the ball inside another one.
// Bricks are destroyed and scored here (pure logic); frame() only renders.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  let remaining = dt;
  let passes = 0;

  while (remaining > 0 && passes++ < 5) {
    const startX = ball.x;
    const startY = ball.y;

    ball.x += ball.vx * remaining;
    ball.y += ball.vy * remaining;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle: swept contact too (a 50ms step at level 6 is 35.5px, deeper than
    // the 12px band + 14px ball — an endpoint band test would be jumped over).
    // Only a descending ball bounces off the paddle.
    const moveX = ball.x - startX;
    const moveY = ball.y - startY;
    let hitT = Infinity;
    let hitAxis = null;
    let hitPaddle = false;
    const hitBricks = [];
    if (ball.vy > 0) {
      const c = sweptContact(startX, startY, moveX, moveY, paddle, ball.r);
      if (c) {
        hitT = c.t;
        hitAxis = c.axis;
        hitPaddle = true;
      }
    }

    // Bricks: swept detection over the movement segment. Every brick touched at
    // the earliest contact is destroyed, and each axis bounces at most once
    // (the seam: two bricks in one pass must not flip vy twice).
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      const c = sweptContact(startX, startY, moveX, moveY, brick, ball.r);
      if (!c) continue;
      if (c.t < hitT - 1e-9) {
        hitT = c.t;
        hitAxis = c.axis;
        hitPaddle = false;
        hitBricks.length = 0;
        hitBricks.push(brick);
      } else if (Math.abs(c.t - hitT) < 1e-9) {
        hitBricks.push(brick);
      }
    }

    if (hitT === Infinity) break; // the pass is done, no contact

    if (hitPaddle) {
      // Stop at the contact point, then bounce off the paddle: the exit angle
      // comes from where the paddle was hit, at the level speed.
      ball.x = startX + moveX * hitT;
      ball.y = startY + moveY * hitT;
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      const speed = ballSpeed(state.level);
      // A dead-center hit would give vx = 0 and a permanent vertical loop:
      // floor the horizontal component so every trajectory stays playable.
      let vx = speed * 0.6 * hit;
      if (Math.abs(vx) < 0.1 * speed) vx = vx >= 0 ? 0.1 * speed : -0.1 * speed;
      // Renormalise to the level speed: the bounce must not speed the ball up.
      ball.vx = vx;
      ball.vy = -Math.sqrt(speed * speed - vx * vx);
      state.combo = 0;
    } else {
      for (const brick of hitBricks) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
      // Stop at the contact point, bounce once (per axis).
      ball.x = startX + moveX * hitT;
      ball.y = startY + moveY * hitT;
      if (hitAxis === 'x') ball.vx = -ball.vx;
      else if (hitAxis === 'y') ball.vy = -ball.vy;
      else {
        ball.vx = -ball.vx;
        ball.vy = -ball.vy;
      }
      // A t = 0 contact means the ball started overlapping: push it back out.
      const brick = hitBricks[0];
      if (hitAxis !== 'y' && ball.x + ball.r > brick.x && ball.x - ball.r < brick.x + brick.w) {
        if (ball.x < brick.x + brick.w / 2) ball.x = brick.x - ball.r;
        else ball.x = brick.x + brick.w + ball.r;
      }
      if (hitAxis !== 'x' && ball.y + ball.r > brick.y && ball.y - ball.r < brick.y + brick.h) {
        if (ball.y < brick.y + brick.h / 2) ball.y = brick.y - ball.r;
        else ball.y = brick.y + brick.h + ball.r;
      }
    }

    remaining *= 1 - hitT; // keep sweeping the rest of the pass
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

