// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  ballSpeed,
  BALL_R,
  PADDLE_Y,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- D1: the ball must bounce off bricks (defect: no bounce at all) ---------

test('D1: the ball bounces off the side of a brick (vx flips), brick destroyed', () => {
  const state = createState(1);
  // Real grid brick: col 2, row 0 → [164,236] x [48,68]
  state.bricks = [makeBricks(1).find((b) => b.x === 164 && b.y === 48)];
  const brick = state.bricks[0];
  // Ball approaching the LEFT face from the left, y fully inside the brick band.
  state.ball = { x: 155, y: 58, r: BALL_R, vx: 200, vy: 0 };
  step(state, 1 / 60);
  assert.equal(brick.alive, false, 'the touched brick must be destroyed');
  assert.ok(state.ball.vx < 0, `side hit must flip vx, got vx=${state.ball.vx}`);
});

// --- D2: sticky — flip without reposition leaves the ball inside the brick --

test('D2: after a brick bounce the ball ends outside the brick', () => {
  const state = createState(1);
  // Real grid brick: col 4, row 4 → [324,396] x [160,180]
  state.bricks = [makeBricks(1).find((b) => b.x === 324 && b.y === 160)];
  const brick = state.bricks[0];
  // Ball just below the brick, climbing: already overlapping at frame start.
  state.ball = { x: 360, y: 185, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, `bottom-face hit must bounce down, got vy=${state.ball.vy}`);
  assert.ok(!collides(state.ball, brick), 'ball must end outside the brick');
});

// --- D3: double inversion on the seam between two bricks --------------------

test('D3: hitting the seam between two bricks bounces once, not twice', () => {
  const state = createState(1);
  // Col 3 [244,316] and col 4 [324,396], row 4 [160,180] — 8px gap, ball
  // diameter 14px: a ball centered in the gap overlaps BOTH bricks.
  state.bricks = makeBricks(1).filter((b) => (b.x === 244 || b.x === 324) && b.y === 160);
  state.ball = { x: 320, y: 185, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, `one bounce per pass: ball must leave downward, got vy=${state.ball.vy}`);
  assert.ok(state.bricks.every((b) => !b.alive), 'both seam bricks destroyed');
});

// --- D4: face vs corner — equal face distances flip both axes ----------------

test('D4: a corner hit (equal penetration on both axes) flips both velocities', () => {
  const state = createState(1);
  // Real grid brick: col 2, row 4 → [164,236] x [160,180]. Ball center 3px left
  // and 3px below the bottom-left corner: the two nearest faces are at equal
  // distance → corner, not a face.
  state.bricks = [makeBricks(1).find((b) => b.x === 164 && b.y === 160)];
  state.ball = { x: 161, y: 183, r: BALL_R, vx: 200, vy: -200 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, `corner hit must flip vx, got vx=${state.ball.vx}`);
  assert.ok(state.ball.vy > 0, `corner hit must flip vy, got vy=${state.ball.vy}`);
});

// --- D5: tunneling at level 6 + the 50ms dt cap (swept detection) ------------

test('D5: a level-6 ball at the 50ms dt cap must not tunnel through a brick', () => {
  const run = (dt) => {
    const state = createState(6);
    // Col 4, row 4 → [324,396] x [160,180]
    state.bricks = [makeBricks(6).find((b) => b.x === 324 && b.y === 160)];
    const brick = state.bricks[0];
    // Ball just below the brick (3px clear), straight up at the level-6 speed:
    // vertical step at dt=0.05 is 710*0.05 = 35.5px > 34px (brick height 20 +
    // ball diameter 14): an endpoint-only test sees NO overlap at either end.
    state.ball = { x: 360, y: 188, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
    step(state, dt);
    return { state, brick };
  };
  // One 50ms step — the dt cap — must bounce…
  const cap = run(0.05);
  assert.ok(cap.state.ball.vy > 0, `no clean pass at the dt cap, got vy=${cap.state.ball.vy}`);
  assert.ok(cap.state.ball.y > 180, 'ball must end below the brick');
  assert.equal(cap.brick.alive, false, 'the tunnelled brick must be destroyed');
  // …and the same 50ms split in three 16.7ms steps must give the same outcome.
  const split = run(1 / 60);
  assert.ok(split.state.ball.vy > 0, 'same outcome when the 50ms are split');
});

// --- D6: paddle — a fast ball must not pass through the band test -----------

test('D6: a fast descending ball is caught by the paddle, not passed through', () => {
  const state = createState(6);
  // Ball descending at the level-6 speed, bottom edge 1px above the paddle face
  // (448). One 50ms step = 35.5px > paddle.h (12) + ball diameter (14) = 26px:
  // the endpoint band test [448,460] is jumped over cleanly.
  state.ball = { x: 320, y: 440, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, `paddle must bounce the ball up, got vy=${state.ball.vy}`);
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y, 'ball must end above the paddle');
});

// --- D7: angle mort — a dead-center paddle hit must keep a horizontal part --

test('D7: a dead-center paddle hit still gives the ball a horizontal component', () => {
  const state = createState(1);
  // Ball exactly over the paddle center: hit offset = 0. Without a floor the
  // paddle bounce sets vx = 0 and the ball loops vertically forever.
  state.ball = { x: 320, y: 441, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(
    Math.abs(state.ball.vx) >= 0.1 * ballSpeed(1),
    `center hit must keep a min |vx|, got vx=${state.ball.vx}`
  );
});

// --- D8: vitesse — a paddle bounce preserves the level speed -----------------

test('D8: a paddle bounce preserves the level speed', () => {
  const state = createState(1);
  // Off-center hit: offset +0.5. Without renormalisation the bounce sets
  // vx = 0.6*speed*0.5 and keeps vy = -speed → norm = sqrt(78²+260²) ≈ 271.4
  // instead of 260: the ball drifts faster than the level speed.
  state.ball = { x: 344, y: 441, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(1)) < 1e-6, `bounce speed must be the level speed, got ${norm}`);
});

